# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">OKSİJENLİ SOLUNUMUN GENEL DENKLEMİ VE EVRELERİ</text>\n  <rect x="22" y="40" width="656" height="36" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="350" y="63" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e3a8a">C₆H₁₂O₆ (Glikoz) + 6 O₂  ⟶  6 CO₂ + 6 H₂O + ATP (Kimyasal Enerji) + Isı</text>\n  <rect x="22" y="88" width="155" height="128" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="99" y="108" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">1. GLİKOLİZ</text>\n  <text x="99" y="128" text-anchor="middle" font-size="10.5" fill="#78350f">Yer: Sitoplazma</text>\n  <text x="99" y="148" text-anchor="middle" font-size="10.2" fill="#78350f">Glikoz (6C) ⟶ 2 Pirüvat (3C)</text>\n  <text x="99" y="168" text-anchor="middle" font-size="10.2" fill="#78350f">Harcanan: 2 ATP</text>\n  <text x="99" y="188" text-anchor="middle" font-size="10.2" font-weight="bold" fill="#78350f">Net: 2 ATP (SDF) + 2 NADH</text>\n  <rect x="189" y="88" width="155" height="128" rx="10" fill="#fce7f3" stroke="#db2777" stroke-width="2"/>\n  <text x="266" y="108" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9d174d">2. PİRÜVAT OKSİDASYONU</text>\n  <text x="266" y="128" text-anchor="middle" font-size="10.5" fill="#831843">Yer: Mitokondri Matriksi</text>\n  <text x="266" y="148" text-anchor="middle" font-size="10.2" fill="#831843">2 Pirüvat (3C) ⟶ 2 Asetil-CoA (2C)</text>\n  <text x="266" y="168" text-anchor="middle" font-size="10.2" fill="#831843">Çıkan: 2 CO₂ + 2 NADH</text>\n  <text x="266" y="188" text-anchor="middle" font-size="10.2" font-weight="bold" fill="#83184d">ATP sentezi gerçekleşmez</text>\n  <rect x="356" y="88" width="155" height="128" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="433" y="108" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">3. SİTRİK ASİT (KREBS)</text>\n  <text x="433" y="128" text-anchor="middle" font-size="10.5" fill="#14532d">Yer: Mitokondri Matriksi</text>\n  <text x="433" y="148" text-anchor="middle" font-size="10.2" fill="#14532d">2 Asetil-CoA döngüye girer</text>\n  <text x="433" y="168" text-anchor="middle" font-size="10.2" fill="#14532d">Çıkan: 4 CO₂, 6 NADH, 2 FADH₂</text>\n  <text x="433" y="188" text-anchor="middle" font-size="10.2" font-weight="bold" fill="#14532d">Net: 2 ATP (SDF)</text>\n  <rect x="523" y="88" width="155" height="128" rx="10" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="600" y="108" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#5b21b6">4. ETS VE KEMİOZMOZ</text>\n  <text x="600" y="128" text-anchor="middle" font-size="10.5" fill="#4c1d95">Yer: Krista (İç Zar)</text>\n  <text x="600" y="148" text-anchor="middle" font-size="10.2" fill="#4c1d95">10 NADH ve 2 FADH₂ yükseltgenir</text>\n  <text x="600" y="168" text-anchor="middle" font-size="10.2" fill="#4c1d95">Son elektron alıcısı: O₂ ⟶ H₂O</text>\n  <text x="600" y="188" text-anchor="middle" font-size="10.2" font-weight="bold" fill="#4c1d95">En çok ATP (Oksidatif Fosf.)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Prokaryotlarda mitokondri olmadığı için tüm evreler sitoplazma ve hücre zarı kıvrımlarında (mezozom) gerçekleşir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">MİTOKONDRİ YAPISI VE MATRİKS REAKSİYONLARI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">MİTOKONDRİNİN YAPISAL ADAPTASYONLARI</text>\n  <text x="35" y="88" font-size="11.2" fill="#7c2d12">• Çift katlı zara sahiptir (dış zar düz, iç zar kıvrımlı).</text>\n  <text x="35" y="112" font-size="11.2" fill="#7c2d12">• Krista: İç zar kıvrımlarıdır; ETS elemanları ve ATP</text>\n  <text x="45" y="128" font-size="11.2" fill="#7c2d12">sentaz enzimlerini taşıyarak yüzey alanını artırır.</text>\n  <text x="35" y="152" font-size="11.2" fill="#7c2d12">• Matriks: İç sıvıdır; halka DNA, RNA, ribozom ve</text>\n  <text x="45" y="168" font-size="11.2" fill="#7c2d12">Krebs döngüsü enzimlerini bulundurur.</text>\n  <text x="35" y="192" font-size="11.2" fill="#7c2d12">• Hücrenin enerji (ATP) santrali olarak görev yapar.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">SİTRİK ASİT (KREBS) DÖNGÜSÜ AKIŞI</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• Asetil-CoA (2C) + Okzaloasetik asit (4C) birleşerek</text>\n  <text x="380" y="104" font-size="11.2" fill="#14532d">6 karbonlu Sitrik asiti oluşturur.</text>\n  <text x="370" y="128" font-size="11.2" fill="#14532d">• Karbon eksilmesiyle (dekarboksilasyon) CO₂ çıkar.</text>\n  <text x="370" y="152" font-size="11.2" fill="#14532d">• NAD⁺ ve FAD koenzimleri H⁺ ve e⁻ alarak indirgenir</text>\n  <text x="380" y="168" font-size="11.2" fill="#14532d">(NADH ve FADH₂ sentezlenir).</text>\n  <text x="370" y="192" font-size="11.2" fill="#14532d">• Substrat düzeyinde fosforilasyonla (SDF) ATP üretilir.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">1 molekül glikoz için Krebs döngüsü 2 tur döner; toplamda 6 CO₂ (2\'si pirüvat oksidasyonunda, 4\'ü Krebs\'te) açığa çıkar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ELEKTRON TAŞIMA SİSTEMİ (ETS) VE FOSFORİLASYON ÇEŞİTLERİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">SUBSTRAT DÜZEYİNDE FOSFORİLASYON (SDF)</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Enzimler yardımıyla organik bir substrattan koparılan</text>\n  <text x="45" y="104" font-size="11.2" fill="#1e3a8a">fosfat grubunun doğrudan ADP\'ye aktarılmasıdır.</text>\n  <text x="35" y="128" font-size="11.2" fill="#1e3a8a">• Glikoliz (net 2 ATP) ve Sitrik Asit Döngüsünde</text>\n  <text x="45" y="144" font-size="11.2" fill="#1e3a8a">(2 ATP) görülür; toplam 4 net ATP üretilir.</text>\n  <text x="35" y="168" font-size="11.2" fill="#1e3a8a">• Tüm canlı hücrelerde (oksijenli/oksijensiz solunum</text>\n  <text x="45" y="184" font-size="11.2" fill="#1e3a8a">ve fermantasyon) ortak olarak gerçekleşir.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">OKSİDATİF FOSFORİLASYON (ETS - KEMİOZMOZ)</text>\n  <text x="370" y="88" font-size="11.2" fill="#581c87">• NADH ve FADH₂\'nin taşıdığı elektronlar kristadaki</text>\n  <text x="380" y="104" font-size="11.2" fill="#581c87">ETS elemanları boyunca kademeli aktarılır.</text>\n  <text x="370" y="128" font-size="11.2" fill="#581c87">• Zarlar arası boşluğa pompalanan protonlar (H⁺),</text>\n  <text x="380" y="144" font-size="11.2" fill="#581c87">ATP sentaz içinden matrikse dönerken ATP üretilir.</text>\n  <text x="370" y="168" font-size="11.2" fill="#581c87">• Son elektron alıcısı O₂\'dir; elektron ve H⁺ alarak</text>\n  <text x="380" y="184" font-size="11.2" fill="#581c87">su (H₂O) oluşturur. En yüksek ATP kazancı buradadır.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Oksijenli solunumda 1 glikozdan yaklaşık 30-32 net ATP sentezlenir; enerjinin kalan kısmı ısı olarak yayılır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
